Scripts.File:
# Configurar-HD.ps1 - move Downloads, Documentos, Videos, Imagens e Musicas para o HD. # Uso (PowerShell como admin): powershell -ExecutionPolicy Bypass -File C:\Windows\Setup\Scripts\Configurar-HD.ps1 -Letra D param([Parameter(Mandatory = $true)][ValidatePattern('^[A-Za-z]$')][string]$Letra)
$raiz = "$($Letra.ToUpper()):\Usuario" if (-not (Test-Path "$($Letra.ToUpper()):\")) { Write-Host "Unidade $Letra`: nao existe."; exit 1 }
$pastas = [ordered]@{ 'Personal' = 'Documentos' '{374DE290-123F-4565-9164-39C4925E467B}' = 'Downloads' 'My Video' = 'Videos' 'My Pictures' = 'Imagens' 'My Music' = 'Musicas' } $usf = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\User Shell Folders' $sf = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Shell Folders' foreach ($k in $pastas.Keys) { $destino = Join-Path $raiz $pastas[$k] $atual = [Environment]::ExpandEnvironmentVariables((Get-ItemProperty $usf).$k) New-Item -ItemType Directory -Path $destino -Force | Out-Null if ($atual -and (Test-Path $atual) -and ($atual -ne $destino)) { & robocopy.exe $atual $destino /E /MOVE /NFL /NDL /NJH /NJS | Out-Null } Set-ItemProperty $usf -Name $k -Value $destino Set-ItemProperty $sf -Name $k -Value $destino -ErrorAction SilentlyContinue Write-Host "$($pastas[$k]) -> $destino" } # Pasta sugerida para a biblioteca da Steam New-Item -ItemType Directory -Path "$($Letra.ToUpper()):\SteamLibrary" -Force | Out-Null Stop-Process -Name explorer -Force Write-Host "Pronto. Na Steam: Configuracoes > Armazenamento > adicionar $($Letra.ToUpper()):\SteamLibrary"

# Apps.ps1 - roda em segundo plano depois do primeiro login (nao segura a area de trabalho)
# Instala: Visual C++ (x64 e x86), .NET 3.5 e Notepad++. Precisa de internet.
# Log: C:\Windows\Setup\Scripts\Apps.log
$ErrorActionPreference = 'Continue'
Start-Transcript -Path 'C:\Windows\Setup\Scripts\Apps.log' -Force | Out-Null

# Espera ate 15 minutos por internet (da tempo de plugar o cabo / instalar driver de rede)
$limite = [datetime]::Now.AddMinutes(15)
$online = $false
while ([datetime]::Now -lt $limite) {
    try {
        $r = [Net.WebRequest]::Create('https://aka.ms'); $r.Method = 'HEAD'; $r.Timeout = 5000
        $r.GetResponse().Close(); $online = $true; break
    } catch { Start-Sleep -Seconds 15 }
}
if (-not $online) {
    Write-Warning 'Sem internet. Rode este script de novo depois: C:\Windows\Setup\Scripts\Apps.ps1'
    Stop-Transcript | Out-Null; exit 0
}

# Visual C++ 2015-2022 (x64 e x86 - muitos jogos usam os dois)
foreach ($arq in 'vc_redist.x64.exe', 'vc_redist.x86.exe') {
    try {
        $dest = Join-Path $env:TEMP $arq
        [Net.WebClient]::new().DownloadFile("https://aka.ms/vs/17/release/$arq", $dest)
        Start-Process -FilePath $dest -ArgumentList '/install /quiet /norestart' -Wait
        Remove-Item $dest -Force -ErrorAction SilentlyContinue
        Write-Host "Instalado: $arq"
    } catch { Write-Warning "Falhou: $arq - $_" }
}

# .NET Framework 3.5 (usa o pendrive se ainda estiver conectado; senao baixa da Microsoft)
$sxs = Get-PSDrive -PSProvider FileSystem | ForEach-Object { Join-Path $_.Root 'sources\sxs' } |
       Where-Object { Test-Path $_ } | Select-Object -First 1
try {
    if ($sxs) { Enable-WindowsOptionalFeature -Online -FeatureName NetFx3 -All -Source $sxs -LimitAccess -NoRestart | Out-Null }
    else      { Enable-WindowsOptionalFeature -Online -FeatureName NetFx3 -All -NoRestart | Out-Null }
    Write-Host 'Instalado: .NET 3.5'
} catch { Write-Warning ".NET 3.5 falhou: $_" }

# Notepad++ via winget (espera o winget ficar pronto)
$winget = "$env:LOCALAPPDATA\Microsoft\WindowsApps\winget.exe"
$limite = [datetime]::Now.AddMinutes(10)
while (-not (Test-Path $winget) -and [datetime]::Now -lt $limite) { Start-Sleep -Seconds 10 }
if (Test-Path $winget) {
    & $winget install --exact --id Notepad++.Notepad++ --silent --scope machine `
        --accept-package-agreements --accept-source-agreements --source winget
} else { Write-Warning 'winget nao encontrado - instale o Notepad++ manualmente.' }

Write-Host 'Apps concluido.'
Stop-Transcript | Out-Null
